// AUTO-GENERATED by hls.py -- do not edit by hand
// schedule length: 3 cycles | FUs: add0, sub0, mul0
//   cycle 1: X_1=A+B
//   cycle 2: Y_1=X_1+A, Z_1=X_1-B
//   cycle 3: Q_1=B*Z_1
`timescale 1ns/1ps
module hls_core #(parameter W = 16) (
    input  wire clk, rst,
    input  wire step,                 // one-cycle pulse: advance the FSM
    input  wire load,                 // one-cycle pulse: write load_val into input load_idx (IDLE only)
    input  wire [3:0] load_idx,
    input  wire [W-1:0] load_val,
    input  wire [3:0] fu_sel,         // which functional unit to observe
    input  wire [3:0] var_sel,        // which variable register to observe
    output wire [4:0] state_out,
    output wire done,
    output reg  [W-1:0] fu_out,
    output reg  [W-1:0] var_out
);
    localparam [4:0] IDLE = 5'd0, DONE = 5'd4;
    reg [4:0] state;
    assign state_out = state;
    assign done = (state == DONE);

    // ---------------- FSM: one state per scheduled cycle ----------------
    always @(posedge clk) begin
        if (rst)       state <= IDLE;
        else if (step) state <= (state == DONE) ? IDLE : state + 5'd1;
    end

    // ---------------- registers ----------------
    reg [W-1:0] r_A;   // primary input
    reg [W-1:0] r_B;   // primary input
    reg [W-1:0] r_X_1;   // result of cycle 1
    reg [W-1:0] r_Y_1;   // result of cycle 2
    reg [W-1:0] r_Z_1;   // result of cycle 2
    reg [W-1:0] r_Q_1;   // result of cycle 3

    // input registers: reset to demo defaults, loadable from switches while IDLE
    always @(posedge clk) begin
        if (rst) begin
            r_A <= 5;
            r_B <= 3;
        end else if (load && state == IDLE) begin
            case (load_idx)
                4'd0: r_A <= load_val;
                4'd1: r_B <= load_val;
                default: ;
            endcase
        end
    end

    // ---------------- functional units with per-state input muxes ----------------
    reg  [W-1:0] add0_a, add0_b;
    wire [W-1:0] add0_y;
    always @* begin
        add0_a = {W{1'b0}}; add0_b = {W{1'b0}};
        case (state)
            5'd1: begin add0_a = r_A; add0_b = r_B; end   // X_1
            5'd2: begin add0_a = r_A; add0_b = r_X_1; end   // Y_1
            default: ;
        endcase
    end
    hls_adder #(.W(W)) u_add0 (.a(add0_a), .b(add0_b), .y(add0_y));
    wire add0_act = (state == 5'd1) || (state == 5'd2);
    reg  [W-1:0] add0_hold;   // last value this FU produced (for observation)
    always @(posedge clk) if (rst) add0_hold <= 0; else if (step && add0_act) add0_hold <= add0_y;
    wire [W-1:0] add0_view = add0_act ? add0_y : add0_hold;

    reg  [W-1:0] sub0_a, sub0_b;
    wire [W-1:0] sub0_y;
    always @* begin
        sub0_a = {W{1'b0}}; sub0_b = {W{1'b0}};
        case (state)
            5'd2: begin sub0_a = r_X_1; sub0_b = r_B; end   // Z_1
            default: ;
        endcase
    end
    hls_subtractor #(.W(W)) u_sub0 (.a(sub0_a), .b(sub0_b), .y(sub0_y));
    wire sub0_act = (state == 5'd2);
    reg  [W-1:0] sub0_hold;   // last value this FU produced (for observation)
    always @(posedge clk) if (rst) sub0_hold <= 0; else if (step && sub0_act) sub0_hold <= sub0_y;
    wire [W-1:0] sub0_view = sub0_act ? sub0_y : sub0_hold;

    reg  [W-1:0] mul0_a, mul0_b;
    wire [W-1:0] mul0_y;
    always @* begin
        mul0_a = {W{1'b0}}; mul0_b = {W{1'b0}};
        case (state)
            5'd3: begin mul0_a = r_B; mul0_b = r_Z_1; end   // Q_1
            default: ;
        endcase
    end
    hls_multiplier #(.W(W)) u_mul0 (.a(mul0_a), .b(mul0_b), .y(mul0_y));
    wire mul0_act = (state == 5'd3);
    reg  [W-1:0] mul0_hold;   // last value this FU produced (for observation)
    always @(posedge clk) if (rst) mul0_hold <= 0; else if (step && mul0_act) mul0_hold <= mul0_y;
    wire [W-1:0] mul0_view = mul0_act ? mul0_y : mul0_hold;

    // ---------------- result registers: written at the end of the op's cycle ----------------
    always @(posedge clk) begin
        if (rst) begin
            r_X_1 <= 0;
            r_Y_1 <= 0;
            r_Z_1 <= 0;
            r_Q_1 <= 0;
        end else if (step) begin
            case (state)
                5'd1: begin r_X_1 <= add0_y; end
                5'd2: begin r_Y_1 <= add0_y; r_Z_1 <= sub0_y; end
                5'd3: begin r_Q_1 <= mul0_y; end
                default: ;
            endcase
        end
    end

    // ---------------- observation muxes ----------------
    always @* begin
        case (fu_sel)
            4'd0: fu_out = add0_view;
            4'd1: fu_out = sub0_view;
            4'd2: fu_out = mul0_view;
            default: fu_out = {W{1'b0}};
        endcase
        case (var_sel)
            4'd0: var_out = r_A;
            4'd1: var_out = r_B;
            4'd2: var_out = r_X_1;
            4'd3: var_out = r_Y_1;
            4'd4: var_out = r_Z_1;
            4'd5: var_out = r_Q_1;
            default: var_out = {W{1'b0}};
        endcase
    end
endmodule
